SourceCode.Declaration:
/// <summary>
/// Opens the dialog for executing the environment data setup.
/// </summary>
class OLK_EnvironmentDataSetupExecuteController extends SysOperationServiceController
{
}

Method.Source:
public static OLK_EnvironmentDataSetupExecuteController construct()
{
    return new OLK_EnvironmentDataSetupExecuteController(
        classStr(OLK_EnvironmentDataSetupExecuteService),
        methodStr(OLK_EnvironmentDataSetupExecuteService, execute),
        SysOperationExecutionMode::Synchronous);
}

public static void main(Args _args)
{
    OLK_EnvironmentDataSetupExecuteController controller = OLK_EnvironmentDataSetupExecuteController::construct();

    controller.parmArgs(_args);

    if (_args && _args.record() && _args.record().TableId == tableNum(OLK_EnvironmentDataSetupTable))
    {
        OLK_EnvironmentDataSetupTable           environment = _args.record();
        OLK_EnvironmentDataSetupExecuteContract contract    = controller.getDataContractObject();

        contract.parmEnvironmentId(environment.EnvironmentId);
    }

    controller.startOperation();
}
